async function(ctx){
  var groups=[[1,ctx.sortBy],[2,ctx.noteType],[3,ctx.publishTime],[4,ctx.searchScope],[5,ctx.location]];
  var wanted=[];
  for(var i=0;i<groups.length;i++){
    var text=String(groups[i][1]||'').trim();
    if(!text||text==='不限')continue;
    if(groups[i][0]===1&&text==='综合')continue;
    wanted.push([groups[i][0],text]);
  }
  if(!wanted.length)return {applied:0,options:[]};
  var u=function(x){var h=0;while(x&&typeof x==='object'&&'_rawValue' in x&&h<8){x=x._rawValue;h++;}return x;};
  var snap=function(){
    try{
      var S=window.__INITIAL_STATE__;
      var f=u(u(u(S.search)||{}).feeds);
      if(!Array.isArray(f))return '0';
      var first=f[0];
      var id=first?(first.id||(first.noteCard&&first.noteCard.noteId)||''):'';
      return f.length+':'+id;
    }catch(e){return '0';}
  };
  var wait=function(ms){return new Promise(function(resolve){setTimeout(resolve,ms);});};
  var panel=function(){return document.querySelector('div.filters-wrapper');};
  if(!panel()){
    var btn=document.querySelector('div.filter');
    if(btn)btn.click();
  }
  var deadline=Date.now()+5000;
  while(!panel()&&Date.now()<deadline){await wait(100);}
  var wrapper=panel();
  if(!wrapper)throw new Error('筛选面板没有打开，无法应用筛选条件');
  var before=snap();
  var applied=[];
  var missing=[];
  for(var j=0;j<wanted.length;j++){
    var index=wanted[j][0]-1;
    var wantedText=wanted[j][1];
    var group=wrapper.querySelectorAll('div.filters')[index];
    if(!group){missing.push(wantedText);continue;}
    var tag=Array.from(group.querySelectorAll('div.tags')).filter(function(el){
      if((el.textContent||'').trim()!==wantedText)return false;
      if(el.getAttribute('aria-hidden')==='true')return false;
      if(!(el.offsetWidth||el.offsetHeight))return false;
      return Number(getComputedStyle(el).opacity||1)>0.5;
    })[0];
    if(!tag){missing.push(wantedText);continue;}
    tag.click();
    applied.push(wantedText);
  }
  if(missing.length)throw new Error('筛选选项不存在：'+missing.join('、'));
  var refresh=Date.now()+6000;
  while(Date.now()<refresh&&snap()===before){await wait(150);}
  return {applied:applied.length,options:applied,refreshed:snap()!==before};
}
